import React, { Dispatch } from 'react';

import { FormFieldReducerAction } from '../state/formfield-state-reducer.js';

/**
 * Common, optional, input-related child nodes props to be bound in input elements and its siblings.
 */
export interface SharedFormFieldProps {
  /** An id for the form control (also needed to link the label). */
  controlId?: string;
  /**
   * When required, any form control within the FormField will also be required.
   * @defaultValue false
   */
  required?: boolean;
  /**
   * When disabled, any form control within the FormField will also be disabled.
   * @defaultValue false
   */
  disabled?: boolean;
}

export interface SharedFormFieldContextProps extends SharedFormFieldProps {
  dispatch?: Dispatch<FormFieldReducerAction>;
}

/**
 * @internal
 * Context provider for `SharedInputProps` props meant to be provided to all its input-related child nodes.
 */
export const _FormFieldContext =
  React.createContext<SharedFormFieldContextProps>({
    controlId: '',
    required: false,
    disabled: false,
    dispatch: undefined,
  });
